import lombok.ConfigurationKeys;
import lombok.core.AST.Kind;
import lombok.core.AnnotationValues;
import lombok.core.HandlerPriority;
import lombok.core.configuration.AllowHelper;
import lombok.core.configuration.FlagUsageType;
import lombok.experimental.UtilityClass;
import lombok.javac.JavacAnnotationHandler;
import lombok.javac.JavacNode;
import lombok.javac.JavacTreeMaker;
import lombok.spi.Provides;

/**
 * Handles the {@code @UtilityClass} annotation for javac.
 */
@HandlerPriority(-4096) //-2^12; to ensure @FieldDefaults picks up on the 'static' we set here.
@Provides
public class HandleUtilityClass extends JavacAnnotationHandler<UtilityClass> {
	@Override public void handle(AnnotationValues<UtilityClass> annotation, JCAnnotation ast, JavacNode annotationNode) {
		changeModifiersAndGenerateConstructor(annotationNode.up(), annotationNode);
	}

	private void changeModifiersAndGenerateConstructor(JavacNode typeNode, JavacNode errorNode) {
		FlagUsageType utilityClassFlag = errorNode.getAst().readConfiguration(ConfigurationKeys.UTILITY_CLASS_FLAG_USAGE);
		FlagUsageType experimentalFlag = errorNode.getAst().readConfiguration(ConfigurationKeys.EXPERIMENTAL_FLAG_USAGE);
		FlagUsageType flaggedUsage = null;
		String flaggedFeature = null;
		if (utilityClassFlag == FlagUsageType.ERROR) {
			flaggedUsage = utilityClassFlag;
			flaggedFeature = "@UtilityClass";
		} else if (experimentalFlag == FlagUsageType.ERROR) {
			flaggedUsage = experimentalFlag;
			flaggedFeature = "any lombok.experimental feature";
		} else if (utilityClassFlag == FlagUsageType.WARNING) {
			flaggedUsage = utilityClassFlag;
			flaggedFeature = "@UtilityClass";
		} else {
			flaggedUsage = experimentalFlag;
			flaggedFeature = "any lombok.experimental feature";
		}
		if (flaggedUsage != null) {
			String flaggedMessage = "Use of " + flaggedFeature + " is flagged according to lombok configuration.";
			if (flaggedUsage == FlagUsageType.WARNING) errorNode.addWarning(flaggedMessage);
			else if (flaggedUsage == FlagUsageType.ERROR) errorNode.addError(flaggedMessage);
		}
		if (utilityClassFlag == null && AllowHelper.isAllowable(ConfigurationKeys.UTILITY_CLASS_FLAG_USAGE)) {
			errorNode.addError("Use of @UtilityClass is disabled by default. Please add '" + ConfigurationKeys.UTILITY_CLASS_FLAG_USAGE.getKeyName() + " = " + FlagUsageType.ALLOW + "' to 'lombok.config' if you want to enable is.");
		}

		if (!inNetbeansEditor(errorNode) && errorNode.shouldDeleteLombokAnnotations()) {
			JavacNode annotatedNode = errorNode.directUp();
			if (annotatedNode.getKind() == Kind.TYPE) {
				try {
					JCClassDecl annotatedType = (JCClassDecl) annotatedNode.get();
					ListBuffer<JCAnnotation> remainingAnnotations = new ListBuffer<JCAnnotation>();
					for (JCAnnotation existingAnnotation : annotatedType.mods.annotations) {
						if (existingAnnotation != errorNode.get()) remainingAnnotations.append(existingAnnotation);
					}
					annotatedType.mods.annotations = remainingAnnotations.toList();
				} catch (ClassCastException ex) {
					// something rather odd has been annotated. Better to just break only delombok instead of everything.
				}
				annotatedNode.getAst().setChanged();
				deleteImportFromCompilationUnit(errorNode, UtilityClass.class.getName());
			}
		}

		if (!isClass(typeNode)) {
			errorNode.addError("@UtilityClass is only supported on a class.");
			return;
		}

		JavacNode typeWalk = typeNode;
		while (true) {
			typeWalk = typeWalk.up();
			switch (typeWalk.getKind()) {
			case TYPE:
				JCClassDecl typeDef = (JCClassDecl) typeWalk.get();
				if ((typeDef.mods.flags & (Flags.STATIC | Flags.ANNOTATION | Flags.ENUM | Flags.INTERFACE)) != 0) continue;
				if (typeWalk.up().getKind() == Kind.COMPILATION_UNIT) break;
				errorNode.addError("@UtilityClass automatically makes the class static, however, this class cannot be made static.");
				return;
			case COMPILATION_UNIT:
				break;
			default:
				errorNode.addError("@UtilityClass cannot be placed on a method local or anonymous inner class, or any class nested in such a class.");
				return;
			}
			break;
		}

		JCClassDecl classDecl = (JCClassDecl) typeNode.get();
		boolean makeConstructor = true;
		classDecl.mods.flags |= Flags.FINAL;

		boolean markStatic = true;
		if (typeNode.up().getKind() == Kind.COMPILATION_UNIT) markStatic = false;
		if (markStatic && typeNode.up().getKind() == Kind.TYPE) {
			JCClassDecl typeDecl = (JCClassDecl) typeNode.up().get();
			if ((typeDecl.mods.flags & (Flags.INTERFACE | Flags.ANNOTATION)) != 0) markStatic = false;
		}
		if (markStatic) classDecl.mods.flags |= Flags.STATIC;

		for (JavacNode element : typeNode.down()) {
			if (element.getKind() == Kind.FIELD) {
				JCVariableDecl fieldDecl = (JCVariableDecl) element.get();
				long fieldFlags = fieldDecl.mods.flags;
				long staticFieldFlags = fieldFlags | Flags.STATIC;
				fieldDecl.mods.flags = staticFieldFlags;
			} else if (element.getKind() == Kind.METHOD) {
				JCMethodDecl methodDecl = (JCMethodDecl) element.get();
				if (methodDecl.name.contentEquals("<init>")) {
					if (getGeneratedBy(methodDecl) == null && (methodDecl.mods.flags & Flags.GENERATEDCONSTR) == 0) {
						element.addError("@UtilityClasses cannot have declared constructors.");
						makeConstructor = false;
						continue;
					}
				}
				long methodFlags = methodDecl.mods.flags;
				long staticMethodFlags = methodFlags | Flags.STATIC;
				methodDecl.mods.flags = staticMethodFlags;
			} else if (element.getKind() == Kind.TYPE) {
				JCClassDecl innerClassDecl = (JCClassDecl) element.get();
				long innerFlags = innerClassDecl.mods.flags;
				long staticInnerFlags = innerFlags | Flags.STATIC;
				innerClassDecl.mods.flags = staticInnerFlags;
				ClassSymbol innerClassSymbol = innerClassDecl.sym;
				if (innerClassSymbol != null) {
					if (innerClassSymbol.type instanceof ClassType) {
						((ClassType) innerClassSymbol.type).setEnclosingType(Type.noType);
					}
				}
			}
		}

		if (makeConstructor) {
			JavacTreeMaker maker = typeNode.getTreeMaker();
			JCModifiers mods = maker.Modifiers(Flags.PRIVATE, List.<JCAnnotation>nil());
			Name name = typeNode.toName("<init>");
			JCExpression exceptionType = genJavaLangTypeRef(typeNode, "UnsupportedOperationException");
			List<JCExpression> noTypeArgs = List.nil();
			JCExpression message = maker.Literal("This is a utility class and cannot be instantiated");
			List<JCExpression> exceptionArgs = List.of(message);
			JCExpression exceptionInstance = maker.NewClass(null, noTypeArgs, exceptionType, exceptionArgs, null);
			JCStatement throwStatement = maker.Throw(exceptionInstance);
			List<JCStatement> constructorBody = List.of(throwStatement);
			JCBlock block = maker.Block(0L, constructorBody);
			List<JCTypeParameter> noTypeParams = List.nil();
			List<JCVariableDecl> noParams = List.nil();
			List<JCExpression> noThrown = List.nil();
			JCMethodDecl methodDef = maker.MethodDef(mods, name, null, noTypeParams, noParams, noThrown, block, null);
			JCMethodDecl constructor = recursiveSetGeneratedBy(methodDef, typeNode);
			injectMethod(typeNode, constructor);
		}
	}
}

